-- Empty relation tables only. No implicit role bindings, app grants or host provisioning.
CREATE TABLE identity_groups(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),key text NOT NULL UNIQUE,name text NOT NULL,kind text NOT NULL CHECK(kind IN ('system','user')),version bigint NOT NULL DEFAULT 1 CHECK(version>0),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE identity_group_members(group_id uuid NOT NULL REFERENCES identity_groups(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES users(public_id) ON DELETE CASCADE,PRIMARY KEY(group_id,user_id));
CREATE INDEX identity_group_members_user_idx ON identity_group_members(user_id);
CREATE TABLE identity_roles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),key text NOT NULL UNIQUE,name text NOT NULL,protected boolean NOT NULL DEFAULT false,version bigint NOT NULL DEFAULT 1 CHECK(version>0));
CREATE TABLE identity_permissions(key text PRIMARY KEY,description text NOT NULL);
CREATE TABLE identity_role_permissions(role_id uuid NOT NULL REFERENCES identity_roles(id) ON DELETE CASCADE,permission_key text NOT NULL REFERENCES identity_permissions(key),PRIMARY KEY(role_id,permission_key));
CREATE TABLE identity_role_bindings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),role_id uuid NOT NULL REFERENCES identity_roles(id),user_id uuid REFERENCES users(public_id) ON DELETE CASCADE,group_id uuid REFERENCES identity_groups(id) ON DELETE CASCADE,scope jsonb NOT NULL DEFAULT '{}' CHECK(jsonb_typeof(scope)='object'),version bigint NOT NULL DEFAULT 1 CHECK(version>0),CHECK(num_nonnulls(user_id,group_id)=1));
CREATE INDEX identity_role_bindings_user_idx ON identity_role_bindings(user_id);
CREATE INDEX identity_role_bindings_group_idx ON identity_role_bindings(group_id);
CREATE TABLE identity_app_access(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),app_id text NOT NULL,user_id uuid REFERENCES users(public_id) ON DELETE CASCADE,group_id uuid REFERENCES identity_groups(id) ON DELETE CASCADE,role_id uuid REFERENCES identity_roles(id),effect text NOT NULL CHECK(effect IN ('allow','deny')),scope jsonb NOT NULL DEFAULT '{}' CHECK(jsonb_typeof(scope)='object'),version bigint NOT NULL DEFAULT 1 CHECK(version>0),CHECK(num_nonnulls(user_id,group_id,role_id)=1));
CREATE TABLE identity_app_grants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),app_id text NOT NULL,permission_key text NOT NULL REFERENCES identity_permissions(key),scope jsonb NOT NULL DEFAULT '{}' CHECK(jsonb_typeof(scope)='object'),state text NOT NULL CHECK(state IN ('enabled','revoked')),version bigint NOT NULL DEFAULT 1 CHECK(version>0));
CREATE TABLE identity_links(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(public_id) ON DELETE CASCADE,issuer text NOT NULL,subject text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(issuer,subject));
CREATE TABLE identity_linux_reservations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(public_id),node_id text NOT NULL,uid bigint NOT NULL CHECK(uid>0 AND uid<4294967295),primary_gid bigint NOT NULL CHECK(primary_gid>0 AND primary_gid<4294967295),state text NOT NULL CHECK(state IN ('reserved','ready','failed','disabled','retired')),version bigint NOT NULL DEFAULT 1 CHECK(version>0),UNIQUE(node_id,uid),UNIQUE(node_id,user_id));
